  ["Report %s, %d characters, selected: press Ctrl+C to copy it."] = "Rapport %s, %d caractères, sélectionné : appuyez sur Ctrl+C pour le copier.",
  ["Report a problem"] = "Signaler un problème",
  ["Report an issue"] = "Signaler un problème",
  ["Report failed"] = "Échec du rapport",
  ["Report too large"] = "Rapport trop grand",
  ["Reporting a problem"] = "Signaler un problème",
  ["Reset everything to defaults"] = "Tout remettre par défaut",
  ["Right after it happens: /dmga report (or the minimap menu, or Status > Report an issue). Step 1: say what went wrong. Step 2: Ctrl+C copies your words and the report together. Step 3: open the link and paste it into a new issue. /dmga help lists every command."] = "Juste après le problème : /dmga report (ou le menu de la minicarte, ou État > Signaler un problème). Étape 1 : dites ce qui s'est mal passé. Étape 2 : Ctrl+C copie vos mots et le rapport ensemble. Étape 3 : ouvrez le lien et collez le tout dans un nouveau ticket. /dmga help liste toutes les commandes.",
  ["Right-click: menu and settings"] = "Clic droit : menu et options",
  ["Rotation by %s."] = "Rotation par %s.",
  ["Rotation from"] = "Rotation de",
  ["Run the setup again"] = "Relancer la configuration",
  ["Saves every line the engine checked into the Watchdog log (same as /dmga snapshot)."] = "Enregistre chaque ligne vérifiée par le moteur dans le journal du Watchdog (comme /dmga snapshot).",
  ["Scale"] = "Échelle",
  ["Seconds before the hit your boss mod announces."] = "Secondes avant le coup annoncé par votre addon de boss.",
  ["Self-heal below"] = "Soin personnel à",
  ["Self-heals"] = "Soins personnels",
  ["Self-heals in raids"] = "Soins personnels en raid",
  ["Self-heals your rotation can suggest (Desperate Prayer, Regrowth, Crimson Vial...) show only at or below this health. 0 = never."] = "Les soins personnels que votre rotation peut proposer (Prière du désespoir, Rétablissement, Fiole cramoisie...) n'apparaissent qu'à cette vie ou moins. 0 = jamais.",
  ["Set key bindings"] = "Définir les raccourcis",
  ["Settings"] = "Options",
  ["Settings copied from %s into %s."] = "Options copiées de %s vers %s.",
  ["Settings open when combat ends."] = "Les options s'ouvriront à la fin du combat.",
  ["Settings this character uses. \"Default\" is shared by every character that has no profile of its own."] = "Options utilisées par ce personnage. « Default » est partagé par tous les personnages sans profil propre.",
  ["Detect boss mods"] = "Afficher les addons de boss trouvés",
  ["Show out of combat"] = "Afficher hors combat",
  ["Show recommendations"] = "Afficher les recommandations",
  ["Show stack count"] = "Afficher le nombre de cumuls",
  ["Show the HUD out of combat while an enemy is targeted."] = "Afficher le HUD hors combat quand un ennemi est ciblé.",
  ["Show with a target"] = "Afficher avec une cible",
  ["Show your on-use trinkets (off-GCD badge on slot 1) when they are ready, with your cooldowns, in combat."] = "Afficher vos bijoux à utiliser (badge hors GCD sur la case 1) quand ils sont prêts, avec vos temps de recharge, en combat.",
  ["SimC default (300 s bosses, short trash)"] = "Valeur SimC (300 s boss, trash court)",
  ["SimC holds or uses cooldowns by how long the fight lasts. Learned: the typical length of your recent fights of the same kind (open world, dungeon/raid trash, bosses, PvP); SimC's defaults until it has 5."] = "SimC garde ou utilise les temps de recharge selon la durée du combat. Appris : la durée typique de vos combats récents du même type (monde ouvert, trash de donjon/raid, boss, JcJ) ; les valeurs de SimC jusqu'à en avoir 5.",
  ["SimulationCraft publishes no rotation for most healing specs (Discipline, Holy Priest, Holy Paladin, Mistweaver, Restoration Shaman, Preservation). For those DMGAssist has its own damage lists, learned from the current class guides, for your damage between heals (SimC's list replaces ours as soon as it publishes one). Healing stays your call. Interrupts, defensives with your boss mod, on-use trinkets, keybinds and your spell choices all work. Restoration Druid has a full SimC list, including cat weaving. A spec with no list at all (some on WoW Forever) follows Blizzard's Assisted Combat."] = "SimulationCraft ne publie pas de rotation pour la plupart des spécialisations de soin (Discipline, Sacré (prêtre), Sacré (paladin), Tisse-brume, Restauration (chaman), Préservation). Pour elles, DMGAssist a ses propres listes de dégâts, apprises des guides de classe actuels, pour vos dégâts entre les soins (la liste de SimC remplace la nôtre dès qu'elle en publie une). Les soins restent votre choix. Interruptions, défensifs avec votre addon de boss, bijoux, raccourcis et vos choix de sorts fonctionnent. Restauration (druide) a une liste SimC complète, y compris le tissage en félin. Une spécialisation sans aucune liste (certaines sur WoW Forever) suit le Combat assisté de Blizzard.",
  ["Single target"] = "Cible unique",
  ["Size, as a percentage of slot 1."] = "Taille, en pourcentage de la case 1.",
  ["Skip the spell in slot 1 three times and it is held for the rest of the fight (\"saving it\"). Cast it yourself and it comes back. Only spells with a real cooldown are held."] = "Passez le sort de la case 1 trois fois et il est retenu pour le reste du combat (« le garder »). Lancez-le vous-même et il revient. Seuls les sorts avec un vrai temps de recharge sont retenus.",
  ["Skip the spell in the first slot three times and it is held until combat ends. Cast it yourself to bring it back."] = "Passez le sort de la première case trois fois et il est retenu jusqu'à la fin du combat. Lancez-le vous-même pour le faire revenir.",
  ["Skipping a spell"] = "Passer un sort",
  ["Small"] = "Petit",
  ["Smart: all in the open world, important ones in instances"] = "Intelligent : tout en monde ouvert ; en donjon/raid seulement ce qui compte",
  ["Smart: boss mod warnings and low health"] = "Intelligent : alertes des addons de boss et vie basse",
  ["Snapshot"] = "Instantané",
  ["Snapshot: %s (%s), %d lines checked. Stored for your report: /dmga report."] = "Instantané : %s (%s), %d lignes vérifiées. Enregistré pour votre rapport : /dmga report.",
  ["Sound alerts"] = "Alertes sonores",
  ["Sounds"] = "Sons",
  ["Spec changed: %s"] = "Spécialisation changée : %s",
  ["Spell name color"] = "Couleur du nom du sort",
  ["Spell name size"] = "Taille du nom du sort",
  ["Spell names under icons"] = "Noms des sorts sous les icônes",
  ["Spells & trinkets"] = "Sorts et bijoux",
  ["Spells & trinkets: untick a spell or trinket to never see it, or tick First when ready to put a spell in slot 1 whenever it can be cast. Kept per spec, through updates."] = "Sorts et bijoux : décochez un sort ou un bijou pour ne jamais le voir, ou cochez En premier dès que prêt pour placer un sort dans la case 1 dès qu'il peut être lancé. Gardé par spécialisation, même après les mises à jour.",
  ["Spells in the list you don't have (or we can't match): %s"] = "Sorts de la liste que vous n'avez pas (ou que nous ne reconnaissons pas) : %s",
  ["Spells matched: %s. Type /dmga help for options."] = "Sorts reconnus : %s. Tapez /dmga help pour les options.",
  ["Rotation spells known"] = "Sorts de la rotation que vous avez",
  ["Spells shown"] = "Sorts affichés",
  ["Stack count"] = "Cumuls",
  ["Stack position"] = "Position des cumuls",
  ["Stack text size"] = "Taille du texte des cumuls",
  ["Gives this character its own profile, starting as a copy of the current settings. Other characters are not affected."] = "Donne à ce personnage son propre profil, en partant d'une copie des options actuelles. Les autres personnages ne sont pas concernés.",
  ["Status"] = "État",
  ["Steady"] = "Fixe",
  ["Save a decision snapshot"] = "Enregistrer un instantané de décision",
  ["Suggest a defensive this long before a big hit that a boss mod announces."] = "Proposer un défensif autant de temps avant un gros coup annoncé par un addon de boss.",
  ["Suggest defensives"] = "Proposer des défensifs",
  ["Suggest interrupts"] = "Proposer des interruptions",
  ["Summary (for reading; the report is what to paste)"] = "Résumé (à lire ; c'est le rapport qu'il faut coller)",
  ["Target mode keybind"] = "Changer avec une touche",
  ["Talents loaded"] = "Talents lus",
  ["Tank essentials"] = "Essentiels du tank",
  ["Tanks: keep active mitigation and your threat DoT up (Guardian: Ironfur stacks, Moonfire on the target)."] = "Tanks : garder la mitigation active et votre DoT de menace (Gardien : cumuls de Fourrure de fer, Éclat lunaire sur la cible).",
  ["Target mode"] = "Mode de cibles",
  ["Target mode: %s."] = "Mode de cibles : %s.",
  ["Targets"] = "Cibles",
  ["Test"] = "Tester",
  ["Defensive test: slot 1 shows %s for 8 seconds."] = "Alerte défensive de test pendant 8 s : la case 1 montre %s, comme quand DBM / BigWigs / LittleWigs annoncent un gros coup.",
  ["Interrupt test: slot 1 shows %s for 8 seconds."] = "Interruption de test pendant 8 s : la case 1 montre %s, comme quand un addon de boss demande un kick ou que votre cible incante.",
  ["Text"] = "Texte",
  ["The DMGAssist_Watchdog addon (Report an issue) is not installed."] = "L'addon DMGAssist_Watchdog (Signaler un problème) n'est pas installé.",
  ["The Default profile can't be deleted."] = "Le profil Default ne peut pas être supprimé.",
  ["The HUD is unlocked: drag it where you like, then lock it in Settings > DMGAssist."] = "Le HUD est déverrouillé : glissez-le où vous voulez, puis verrouillez-le dans Options > DMGAssist.",
  ["The icons"] = "Les icônes",
  ["The main icon is darkened until your GCD or cast is about to end, then flashes: press it then."] = "L'icône principale est assombrie jusqu'à ce que votre GCD ou incantation soit presque fini, puis elle clignote : appuyez à ce moment-là.",
  ["The next spell, plus up to two after it."] = "Le prochain sort, plus jusqu'à deux après.",
  ["Shows where each pick came from: SimC, Assisted Combat, Blizzard rules, or a guess."] = "La file avec l'origine de chaque choix (SimC, assistant, règles de Blizzard, estimation).",
  ["The report could not be built:"] = "Le rapport n'a pas pu être créé :",
  ["The report did not fit in the window. Type /dmgw status and paste what it prints instead."] = "Le rapport ne tenait pas dans la fenêtre. Tapez /dmgw status et collez plutôt ce qui s'affiche.",
  ["Thick"] = "Épais",
  ["Thick outline"] = "Contour épais",
  ["Thin"] = "Fin",
  ["This character"] = "Ce personnage",
  ["This character now has its own profile: %s."] = "Ce personnage a maintenant son propre profil : %s.",
  ["Three questions: where the HUD goes, how big, and when it shows."] = "Trois questions : où va le HUD, quelle taille, et quand il s'affiche.",
  ["To report a problem or give feedback: press Report an issue (or type /dmga report). It walks you through it: say what went wrong, copy the report, paste it on the issue page."] = "Pour signaler un problème ou donner un avis : appuyez sur Signaler un problème (ou tapez /dmga report). Il vous guide : dites ce qui s'est mal passé, copiez le rapport, collez-le sur la page des tickets.",
  ["Top left"] = "En haut à gauche",
  ["Top right"] = "En haut à droite",
  ["Top-left corner (docked)"] = "Coin supérieur gauche (ancré)",
  ["Top-right corner"] = "Coin supérieur droit",
  ["Trinkets"] = "Bijoux",
  ["Troubleshooting"] = "Dépannage",
  ["Show both options when unsure"] = "Embranchements à deux sorts",
  ["Unlock to drag the icons; they are also shown while this panel is open."] = "Déverrouillez pour glisser les icônes ; elles sont aussi affichées tant que ce panneau est ouvert.",
  ["Upcoming adds, AoE, tank hits and interrupts: used for defensives, interrupts and SimC's add timing."] = "Adds, zone, coups sur le tank et interruptions à venir : utilisés pour les défensifs, les interruptions et le timing des adds de SimC.",
  ["Own profile"] = "Profil propre",
  ["Use major cooldowns"] = "Utiliser les temps de recharge sur",
  ["Use the suggestions"] = "Utiliser les suggestions",
  ["Used when \"AoE target count\" is Custom: this many targets or more counts as AoE."] = "Utilisé quand « Nombre de cibles pour la zone » est Personnalisé : à partir de ce nombre de cibles, c'est de la zone.",
  ["Used when the count isn't available. The key binding switches during a fight."] = "Utilisé quand le nombre n'est pas disponible. Le raccourci change le mode pendant un combat.",
  ["Version"] = "Version",
  ["Warn about missing keybinds"] = "Avertir des raccourcis manquants",
  ["Warning: data for %s loaded at once; using %s."] = "Attention : les données de %s ont été chargées en même temps ; %s est utilisé.",
  ["Watchdog (diagnostics)"] = "Watchdog (diagnostic)",
  ["Welcome to DMGAssist"] = "Bienvenue dans DMGAssist",
  ["What were you doing? (for example: 5 dummies, a Mythic+ pull, a raid boss, solo)"] = "Que faisiez-vous ? (par exemple : 5 mannequins, un pull en mythique+, un boss de raid, en solo)",
  ["When"] = "Quand",
  ["When a hidden resource decides (e.g. 4 or 5 combo points), show both spells; the game makes the right one visible."] = "Quand une ressource cachée décide (p. ex. 4 ou 5 points de combo), afficher les deux sorts ; le jeu rend le bon visible.",
  ["When should it show?"] = "Quand doit-il s'afficher ?",
  ["When to show"] = "Quand afficher",
  ["When your boss mod warns of AoE damage, show Power Word: Radiance, then Shield, until enough Atonements are up."] = "Quand votre addon de boss annonce des dégâts de zone, afficher Mot de pouvoir : Radiance, puis Bouclier, jusqu'à avoir assez d'Expiations.",
  ["Where should the recommendations go?"] = "Où mettre les recommandations ?",
  ["Where the rotation comes from"] = "D'où vient la rotation",
  ["Where the small badge for spells pressed alongside slot 1 (no GCD, e.g. Ironfur) sits."] = "Où se place le petit badge des sorts appuyés en même temps que la case 1 (sans GCD, p. ex. Fourrure de fer).",
  ["Whisper"] = "Chuchotement",
  ["With \"Bosses and big pulls\": this many enemies or more counts as a big pull."] = "Avec « Boss et gros pulls » : à partir de ce nombre d'ennemis, c'est un gros pull.",
  ["With DBM, BigWigs or LittleWigs, a defensive is shown a few seconds before a big hit they warn about (lighter ones first; on cooldown, the next). Also when you are low. Integrations has buttons to test both."] = "Avec DBM, BigWigs ou LittleWigs, un défensif est affiché quelques secondes avant un gros coup qu'ils annoncent (les plus légers d'abord ; en recharge, le suivant). Aussi quand votre vie est basse. Intégrations a des boutons pour tester les deux.",
  ["With a controller (the game's gamepad support), keybinds show as controller buttons, for example LT+A."] = "Avec une manette (la prise en charge des manettes du jeu), les raccourcis s'affichent comme des boutons de manette, par exemple LT+A.",
  ["Xbox (A B X Y, LB RB)"] = "Xbox (A B X Y, LB RB)",
  ["You have unspent talent points: press N to open your talents."] = "Il vous reste des points de talent : appuyez sur N pour ouvrir vos talents.",
  ["You know enough of this spec's spells now: DMGAssist's priority list leads."] = "Vous connaissez maintenant assez de sorts de cette spécialisation : la liste de priorités de DMGAssist mène.",
  ["Your choices"] = "Vos choix",
  ["Spec default"] = "Point de bascule de votre spécialisation",
  ["Your spec's switch point comes from its SimC list (when it uses an AoE list): the count where it changes."] = "Le point de bascule de votre spécialisation vient de sa liste SimC (quand elle utilise une liste de zone) : le nombre où elle change.",
  ["available (used as a second opinion)"] = "disponible (utilisé comme second avis)",
  ["held"] = "retenu",
  ["installed"] = "installé",
  ["learned"] = "appris",
  ["learning (SimC default until then)"] = "en apprentissage : valeur SimC pour l'instant",
  ["leveling: following Blizzard's Assisted Combat until you know more of this spec's spells"] = "montée de niveau : suit le Combat assisté de Blizzard jusqu'à ce que vous connaissiez plus de sorts de cette spécialisation",
  ["manual"] = "manuel",
  ["no"] = "non",
  ["no SimC list for this spec: DMGAssist's own list, learned from the class guides"] = "pas de liste SimC pour cette spécialisation : liste propre de DMGAssist, apprise des guides de classe",
  ["no SimC list for this spec: following Blizzard's Assisted Combat"] = "pas de liste SimC pour cette spécialisation : suit le Combat assisté de Blizzard",
  ["none"] = "aucun",
  ["none available"] = "aucun disponible",
  ["none set (Settings > DMGAssist > Set key bindings)"] = "aucun défini (Options > DMGAssist > Définir les raccourcis)",
  ["not available"] = "non disponible",
  ["not installed"] = "non installé",
  ["not on your bars"] = "pas sur vos barres",
  ["off"] = "désactivé",
  ["on a bar, no key"] = "sur une barre, sans touche",
  ["ready"] = "prêt",
  ["starter spec: following Blizzard's Assisted Combat until you choose a specialization"] = "spécialisation de départ : suit le Combat assisté de Blizzard jusqu'à ce que vous choisissiez une spécialisation",
  ["target"] = "cible",
  ["targets"] = "cibles",
  ["then paste your report with |cffffffffCtrl+V|r and press Create. A screenshot helps too."] = "puis collez votre rapport avec |cffffffffCtrl+V|r et appuyez sur Create. Une capture d'écran aide aussi.",
  ["trinket"] = "bijou",
  ["trinket, bottom slot"] = "bijou, emplacement du bas",
  ["trinket, top slot"] = "bijou, emplacement du haut",
  ["yes"] = "oui",
  ["|cffffd100Step 1.|r What went wrong? What did you expect instead?"] = "|cffffd100Étape 1.|r Qu'est-ce qui s'est mal passé ? Qu'attendiez-vous à la place ?",
  ["|cffffd100Step 2.|r Click the box below and press |cffffffffCtrl+C|r. Your words above are included."] = "|cffffd100Étape 2.|r Cliquez dans la case ci-dessous et appuyez sur |cffffffffCtrl+C|r. Vos mots ci-dessus sont inclus.",
  ["|cffffd100Step 3.|r Open this page in your browser (click it, Ctrl+C, paste it in the address bar),"] = "|cffffd100Étape 3.|r Ouvrez cette page dans votre navigateur (cliquez dessus, Ctrl+C, collez-la dans la barre d'adresse),",
  ["Download (CurseForge)"] = "Télécharger (CurseForge)",
  ["Below max level, and for a new character's starter spec, Blizzard's Assisted Combat leads while you know few of the spells the priority list expects; DMGAssist's list takes over by itself as you learn more. New spells without a key and unspent talent points get one chat line. Combat > Leveling."] = "Sous le niveau maximum, et avec la spécialisation de départ d'un nouveau personnage, le Combat assisté de Blizzard mène tant que vous connaissez peu des sorts attendus par la liste de priorités ; la liste de DMGAssist prend le relais toute seule à mesure que vous en apprenez. Les nouveaux sorts sans touche et les points de talent restants donnent une ligne dans le chat. Combat > Montée de niveau.",
  ["Fits your UI"] = "S'intègre à votre interface",
  ["Move the HUD in Blizzard's Edit Mode. Masque skins the icons. With a controller, keybinds show as its buttons (Display > Controller button names). Titan Panel and ElvUI data texts get a DMGAssist launcher. Addon authors: DMGAssistAPI."] = "Déplacez le HUD dans le mode Édition de Blizzard. Masque habille les icônes. Avec une manette, les raccourcis s'affichent comme ses boutons (Affichage > Noms des boutons de manette). Titan Panel et les textes de données d'ElvUI ont un lanceur DMGAssist. Pour les auteurs d'addons : DMGAssistAPI.",
  ["DMGAssist is off for %s. /dmga spec on turns it back on."] = "DMGAssist est désactivé pour %s. /dmga spec on le réactive.",
  ["DMGAssist is on for %s."] = "DMGAssist est activé pour %s.",
  ["DMGAssist on or off for the spec you are in (an alt's healing spec, for example)"] = "DMGAssist activé ou désactivé pour la spécialisation actuelle (par exemple la spécialisation de soin d'un reroll)",
  ["Like your action bars: an icon turns red when your target is out of that spell's range, and slot 1 turns blue when you are short of resource for it."] = "Comme sur vos barres d'action : une icône devient rouge quand votre cible est hors de portée de ce sort, et la case 1 devient bleue quand il vous manque la ressource.",
  ["Use DMGAssist on this spec"] = "Utiliser DMGAssist sur cette spécialisation",
  ["Out of range and resource colors"] = "Couleurs de portée et de ressource",
  ["list recommended spells that have no keybind"] = "lister les sorts qui peuvent être recommandés et n'ont pas de raccourci",
  ["test the defensive alert (8 seconds)"] = "simuler une alerte défensive de votre addon de boss (8 s), pour vérifier qu'elle s'affiche",
  ["refresh keybinds"] = "relire les raccourcis",
  ["report an issue or give feedback: describe it, copy the report, open the issue page"] = "signaler un problème ou donner un avis : décrivez-le, copiez le rapport, ouvrez la page des tickets",
  ["save a full decision trace for troubleshooting"] = "enregistrer une trace complète des décisions pour le dépannage",
  ["test the interrupt alert, Assisted Combat, or boss mod detection"] = "tester l'interruption, l'assistant de Blizzard et la détection des addons de boss",
  ["the three setup questions again (where, how big, when to show)"] = "les trois questions de configuration à nouveau (où, quelle taille, quand afficher)",
  ["Use DMGAssist on %s"] = "Utiliser DMGAssist sur %s",
  ["Reload the interface now to switch the language?"] = "Recharger l'interface maintenant pour changer de langue ?",
  ["Reload now"] = "Recharger",
  ["Later"] = "Plus tard",
  ["Learned timing"] = "Temps appris",
  ["Forget learned timing"] = "Oublier les temps appris",
  ["DMGAssist learns how long your cooldowns really take, including talents, gear and haste it can't see, and which spells to leave to Blizzard's assistant. It's saved for your whole account and gets better as you play. Forget it to start over, for example after a big talent or gear change. Your settings are kept."] = "DMGAssist apprend la durée réelle de vos temps de recharge, y compris les talents, l'équipement et la hâte qu'il ne voit pas, et quels sorts laisser au Combat assisté de Blizzard. C'est enregistré pour tout votre compte et s'améliore au fil du jeu. Oubliez-le pour repartir de zéro, par exemple après un gros changement de talents ou d'équipement. Vos réglages sont conservés.",
  ["Learned cooldown timing forgotten. DMGAssist learns again from your next fight."] = "Temps de recharge appris oubliés. DMGAssist réapprend dès votre prochain combat.",
  ["Not in combat: try again after the fight."] = "Pas en combat : réessayez après le combat.",
  ["forget learned cooldown timing and start learning again"] = "oublier les temps de recharge appris et réapprendre",
  ["Slot 1 changes"] = "Changements de la case 1",
  ["Steady (recommended)"] = "Stable (conseillé)",
  ["Fast"] = "Rapide",
  ["Steady: once you're about to press, slot 1 stays put; a spell that becomes ready at that moment shows in slot 2 and moves up after your press. Fast: slot 1 follows every change sooner, for players who react quickly."] = "Stable : quand vous êtes sur le point d'appuyer, la case 1 ne bouge plus ; un sort qui devient prêt à ce moment s'affiche en case 2 et monte après votre appui. Rapide : la case 1 suit chaque changement plus tôt, pour les joueurs aux réflexes rapides.",
  ["A dark edge around the letters keeps them readable on bright icons."] = "Un contour sombre autour des lettres les garde lisibles sur les icônes claires.",
  ["A dark panel behind the icons."] = "Un panneau sombre derrière les icônes.",
  ["A glow around slot 1. Only slot 1 moves, so it always draws your eye first."] = "Une lueur autour de la case 1. Seule la case 1 bouge, elle attire donc toujours le regard en premier.",
  ["A line around the frame."] = "Une ligne autour du cadre.",
  ["A pick DMGAssist isn't sure about (the game hides a value it needs) is shown slightly faded."] = "Un choix dont DMGAssist n'est pas sûr (le jeu cache une valeur nécessaire) est affiché légèrement estompé.",
  ["A small gold-edged icon on slot 1 for an on-use trinket or a potion, when it's time to use it. Quieter than the red one: worth pressing, never urgent."] = "Une petite icône à bord doré sur la case 1 pour un bijou à utiliser ou une potion, quand c'est le moment. Plus discrète que la rouge : utile, jamais urgente.",
  ["A small red-edged icon on slot 1 for everything that keeps you alive, for every class: defensive cooldowns, self-heals, tank mitigation like Ironfur. It pulses while you need it now."] = "Une petite icône à bord rouge sur la case 1 pour tout ce qui vous garde en vie, pour chaque classe : temps de recharge défensifs, soins personnels, atténuation de tank comme Fourrure de fer. Elle pulse tant que vous en avez besoin.",
  ["A sound for each kind of alert, so you hear it even when you're not looking. Choose None to silence one."] = "Un son pour chaque type d'alerte, pour l'entendre même sans regarder. Choisissez Aucun pour en couper un.",
  ["A thin bar under slot 1 that empties with your global cooldown."] = "Une fine barre sous la case 1 qui se vide avec votre temps de recharge global.",
  ["Action bars and keybinds"] = "Barres d'action et raccourcis",
  ["Alerts and effects"] = "Alertes et effets",
  ["All DMGAssist sounds on or off."] = "Tous les sons de DMGAssist activés ou désactivés.",
  ["Answer the first-time questions again, bind keys, or start over."] = "Répondre à nouveau aux questions de départ, assigner des touches ou tout recommencer.",
  ["Before big hits and when your health is low, a defensive cooldown appears in the red-edged defensive icon on slot 1, pulsing."] = "Avant les gros coups et quand votre vie est basse, un défensif apparaît dans l'icône défensive à bord rouge de la case 1, en pulsant.",
  ["Blizzard's Assisted Combat"] = "Combat assisté de Blizzard",
  ["DBM, BigWigs and LittleWigs warn about upcoming hits, adds and casts, so defensives and interrupts come on time."] = "DBM, BigWigs et LittleWigs préviennent des coups, renforts et incantations à venir, pour que défensifs et interruptions arrivent à temps.",
  ["Defensive icon (staying alive)"] = "Icône défensive (rester en vie)",
  ["Discipline Priest: Atonement"] = "Prêtre Discipline : Expiation",
  ["Extra space between slot 1 and slot 2, so slot 1 stands apart and its small icons have room."] = "Espace supplémentaire entre la case 1 et la case 2, pour que la case 1 se détache et que ses petites icônes aient de la place.",
  ["For characters below max level, or with talents far from the usual build."] = "Pour les personnages sous le niveau maximum, ou aux talents très éloignés du build habituel.",
  ["For tanks: how many stacks of your mitigation buff are up (Guardian Druid: Ironfur), counted from your casts."] = "Pour les tanks : combien de cumuls de votre amélioration d'atténuation sont actifs (druide gardien : Fourrure de fer), comptés à partir de vos sorts.",
  ["Frame and title"] = "Cadre et titre",
  ["Getting started"] = "Pour commencer",
  ["Healing spells in your own kit, for damage dealers and tanks (not healer rotations)."] = "Les sorts de soin de votre propre kit, pour les classes de dégâts et les tanks (pas les rotations de soigneur).",
  ["Hide the icons outside combat (they still show with an enemy targeted, if the next option is on)."] = "Masquer les icônes hors combat (elles restent visibles avec un ennemi ciblé si l'option suivante est activée).",
  ["Hide the icons when you don't need them."] = "Masquer les icônes quand vous n'en avez pas besoin.",
  ["Hide the icons while you're in a vehicle (one with its own action bar)."] = "Masquer les icônes dans un véhicule (avec sa propre barre d'action).",
  ["How DMGAssist decides between the single-target and the multi-target rotation."] = "Comment DMGAssist choisit entre la rotation monocible et la rotation multicible.",
  ["How big the icons are and the space between them. To move them, unlock on the first page and drag, or use Blizzard's Edit Mode."] = "La taille des icônes et l'espace entre elles. Pour les déplacer, déverrouillez-les sur la première page et faites-les glisser, ou utilisez le mode Édition de Blizzard.",
  ["How dark the background panel is."] = "L'opacité du panneau de fond.",
  ["How many icons: slot 1 is the spell to press now, slots 2 and 3 are what comes after it."] = "Combien d'icônes : la case 1 est le sort à lancer maintenant, les cases 2 et 3 ce qui suit.",
  ["How many spells are shown, and which kinds of spells DMGAssist may suggest."] = "Combien de sorts sont affichés, et quels types de sorts DMGAssist peut suggérer.",
  ["How solid slots 2 and 3 are. A little lower keeps your eye on slot 1."] = "L'opacité des cases 2 et 3. Un peu moins garde votre regard sur la case 1.",
  ["How solid the whole HUD is: lower lets you see through it."] = "L'opacité de tout le HUD : moins laisse voir à travers.",
  ["How the icons tell you when to press, and what needs your attention most."] = "Comment les icônes vous indiquent quand appuyer, et ce qui demande le plus votre attention.",
  ["How visible that line is."] = "La visibilité de cette ligne.",
  ["In combat the game hides some values from addons (combo points, for example). How to handle them."] = "En combat, le jeu cache certaines valeurs aux addons (les points de combo, par exemple). Comment les gérer.",
  ["In combat, at or below this much health a defensive is suggested."] = "En combat, à ce niveau de vie ou en dessous, un défensif est suggéré.",
  ["Items icon (trinkets and potions)"] = "Icône d'objets (bijoux et potions)",
  ["Its size, as a percentage of slot 1. Larger also covers more of slot 1: move it out with the sliders below."] = "Sa taille, en pourcentage de la case 1. Plus grande, elle couvre aussi davantage la case 1 : décalez-la avec les curseurs ci-dessous.",
  ["Keybinds and spell names"] = "Raccourcis et noms des sorts",
  ["Move down / up"] = "Déplacer bas / haut",
  ["Move left / right"] = "Déplacer gauche / droite",
  ["NOW above slot 1 and NEXT above slots 2 and 3."] = "MAINTENANT au-dessus de la case 1 et SUIVANT au-dessus des cases 2 et 3.",
  ["Nudges it down (below 0) or up (above 0), in pixels, so it doesn't cover slot 1."] = "La décale vers le bas (sous 0) ou le haut (au-dessus de 0), en pixels, pour qu'elle ne couvre pas la case 1.",
  ["Nudges it left (below 0) or right (above 0), in pixels, so it doesn't cover slot 1."] = "La décale vers la gauche (sous 0) ou la droite (au-dessus de 0), en pixels, pour qu'elle ne couvre pas la case 1.",
  ["Only for Discipline Priests: spread Atonement before big group damage."] = "Uniquement pour les prêtres Discipline : répandre Expiation avant de gros dégâts de groupe.",
  ["Optional lines and decoration around the icons."] = "Lignes et décorations facultatives autour des icônes.",
  ["Out of combat, hide the icons while you're mounted."] = "Hors combat, masquer les icônes quand vous êtes sur une monture.",
  ["Position"] = "Position",
  ["Potion: %s. Shown in the items icon when SimC uses a potion (with your big cooldowns). Right-click the box to remove it."] = "Potion : %s. Affichée dans l'icône d'objets quand SimC utilise une potion (avec vos gros temps de recharge). Clic droit sur la case pour la retirer.",
  ["Potion: drag a potion from your bags onto this box to add it to your rotation (this spec only). It shows in the items icon when SimC uses a potion."] = "Potion : faites glisser une potion de vos sacs sur cette case pour l'ajouter à votre rotation (cette spécialisation seulement). Elle s'affiche dans l'icône d'objets quand SimC utilise une potion.",
  ["Profiles"] = "Profils",
  ["Settings can be shared by all your characters (Default) or kept for this character only."] = "Les réglages peuvent être partagés par tous vos personnages (Par défaut) ou gardés pour ce personnage seulement.",
  ["Setup and reset"] = "Configuration et réinitialisation",
  ["Show a defensive cooldown (Barkskin, Shield Wall, Survival of the Fittest...) in the defensive icon when you need one."] = "Afficher un défensif (Écorce, Mur protecteur, Survie du plus fort...) dans l'icône défensive quand vous en avez besoin.",
  ["Show the key that casts each spell on its icon."] = "Afficher sur chaque icône la touche qui lance le sort.",
  ["Show the spells to press. Off hides the icons completely (the key binding and /dmga on | off do the same)."] = "Afficher les sorts à lancer. Désactivé masque entièrement les icônes (le raccourci et /dmga on | off font de même).",
  ["Show your interrupt (Kick, Pummel, Wind Shear...) in slot 1 when your target casts something interruptible."] = "Afficher votre interruption (Coup de pied, Volée de coups, Cisaille de vent...) en case 1 quand votre cible incante quelque chose d'interruptible.",
  ["Show your on-use trinkets when they are ready, in combat, at the moments SimC uses them (with your cooldowns)."] = "Afficher vos bijoux à utiliser quand ils sont prêts, en combat, aux moments où SimC les utilise (avec vos temps de recharge).",
  ["Shows, for 8 seconds, the defensive DMGAssist would suggest before a big hit, in the defensive icon."] = "Affiche pendant 8 secondes, dans l'icône défensive, le défensif que DMGAssist suggérerait avant un gros coup.",
  ["Single target or AoE"] = "Monocible ou zone",
  ["Size"] = "Taille",
  ["Size and spacing"] = "Taille et espacement",
  ["Some cooldowns are saved or spent depending on how long the fight is expected to last."] = "Certains temps de recharge sont gardés ou utilisés selon la durée prévue du combat.",
  ["Space after the main icon"] = "Espace après l'icône principale",
  ["Stack counter"] = "Compteur de cumuls",
  ["The color of the key text."] = "La couleur du texte de la touche.",
  ["The color of the spell names."] = "La couleur des noms des sorts.",
  ["The font for keybinds, spell names and labels on the icons."] = "La police des raccourcis, noms de sorts et libellés sur les icônes.",
  ["The game's own rotation helper. DMGAssist asks it about things the game hides from addons."] = "L'assistant de rotation du jeu lui-même. DMGAssist l'interroge sur ce que le jeu cache aux addons.",
  ["The size of everything at once, icons and text."] = "La taille de tout à la fois, icônes et texte.",
  ["The size of slot 1, the spell to press now."] = "La taille de la case 1, le sort à lancer maintenant.",
  ["The size of slots 2 and 3, what comes next."] = "La taille des cases 2 et 3, ce qui suit.",
  ["The size of the callout text."] = "La taille du texte des annonces.",
  ["The size of the key text."] = "La taille du texte de la touche.",
  ["The size of the spell names."] = "La taille des noms des sorts.",
  ["The size of the stack number."] = "La taille du nombre de cumuls.",
  ["The sound played for this alert."] = "Le son joué pour cette alerte.",
  ["The space between each icon."] = "L'espace entre chaque icône.",
  ["The space between the icons and the frame's edge (visible with a background or border)."] = "L'espace entre les icônes et le bord du cadre (visible avec un fond ou une bordure).",
  ["The spell's name under each icon."] = "Le nom du sort sous chaque icône.",
  ["The text on and under the icons."] = "Le texte sur et sous les icônes.",
  ["Tools for finding out why DMGAssist picked something, and for reporting a problem."] = "Des outils pour comprendre pourquoi DMGAssist a choisi quelque chose, et pour signaler un problème.",
  ["Trinkets you activate yourself. A ready one appears in the gold-edged items icon on slot 1 (bottom-left by default); press it alongside slot 1."] = "Les bijoux que vous activez vous-même. Un bijou prêt apparaît dans l'icône d'objets à bord doré de la case 1 (en bas à gauche par défaut) ; utilisez-le en plus de la case 1.",
  ["Turn DMGAssist on or off, move it, and pick its language. Everything else is on the pages below: Combat (what it recommends), Display (how it looks), Sounds, Integrations, Advanced."] = "Activer ou désactiver DMGAssist, le déplacer et choisir sa langue. Tout le reste se trouve sur les pages ci-dessous : Combat (ce qu'il recommande), Affichage (son apparence), Sons, Intégrations, Avancé.",
  ["Used when \"Fight length\" is Custom: the fight length assumed, in seconds."] = "Utilisé quand « Durée du combat » est Personnalisée : la durée supposée, en secondes.",
  ["What to recommend"] = "Que recommander",
  ["When the icons show"] = "Quand les icônes s'affichent",
  ["Where DMGAssist finds the key for each spell: Blizzard's bars, Bartender, ElvUI, Dominos."] = "Où DMGAssist trouve la touche de chaque sort : barres de Blizzard, Bartender, ElvUI, Dominos.",
  ["Where the key text sits on the icon."] = "Où se place le texte de la touche sur l'icône.",
  ["Where the stack number sits."] = "Où se place le nombre de cumuls.",
  ["Which part of slot 1 it sits on. Bottom-left by default."] = "Sur quelle partie de la case 1 elle se place. En bas à gauche par défaut.",
  ["Which part of slot 1 it sits on. Top-left by default."] = "Sur quelle partie de la case 1 elle se place. En haut à gauche par défaut.",
  ["Your interrupt takes slot 1 when an enemy casts something worth stopping."] = "Votre interruption prend la case 1 quand un ennemi incante quelque chose qui vaut la peine d'être stoppé.",
  ["Top-left corner"] = "Coin supérieur gauche",
  ["Bottom-left corner"] = "Coin inférieur gauche",
  ["Bottom-right corner"] = "Coin inférieur droit",
  ["Settings open as soon as the game allows it (after combat)."] = "Les réglages s'ouvriront dès que le jeu le permettra (après le combat).",
  ["No potions in your bags"] = "Aucune potion dans vos sacs",
  ["Potion for this spec"] = "Potion pour cette spécialisation",
  ["Potion removed for this spec."] = "Potion retirée pour cette spécialisation.",
  ["Potion set for this spec: %s."] = "Potion pour cette spécialisation : %s.",
  ["Potion: %s. Shown in the items icon when SimC uses a potion (with your big cooldowns). Click the box to change it, right-click to remove it."] = "Potion : %s. Affichée dans l'icône d'objets quand SimC utilise une potion (avec vos gros temps de recharge). Cliquez sur la case pour la changer, clic droit pour la retirer.",
  ["Potion: click this box and pick one of the potions in your bags to add it to your rotation (this spec only). It shows in the items icon when SimC uses a potion."] = "Potion : cliquez sur cette case et choisissez une potion de vos sacs pour l'ajouter à votre rotation (cette spécialisation seulement). Elle s'affiche dans l'icône d'objets quand SimC utilise une potion.",
  ["Type /dmga potion and shift-click a potion to choose it."] = "Tapez /dmga potion puis Maj+clic sur une potion pour la choisir.",
  ["choose the potion for this spec (shift-click it), or /dmga potion off"] = "choisir la potion de cette spécialisation (Maj+clic dessus), ou /dmga potion off",
  ["Addons DMGAssist works with:"] = "Addons avec lesquels DMGAssist fonctionne :",
  ["Check"] = "Vérifier",
  ["DMGAssist works with these when they are installed, with nothing to set up: Masque skins its icons, ElvUI, Bartender and Dominos bars give the keybinds, Titan Panel and ElvUI get a launcher, WeakAuras can read its picks."] = "DMGAssist fonctionne avec ceux-ci quand ils sont installés, sans rien régler : Masque habille ses icônes, les barres d'ElvUI, Bartender et Dominos donnent les raccourcis, Titan Panel et ElvUI ont un lanceur, WeakAuras peut lire ses choix.",
  ["Lists in chat each supported addon: in use, found, or not installed (also /dmga addons)."] = "Liste dans le chat chaque addon pris en charge : utilisé, trouvé ou non installé (aussi /dmga addons).",
  ["Other addons"] = "Autres addons",
  ["Other addons in use"] = "Autres addons utilisés",
  ["Preview. Back in its place when you close the settings."] = "Aperçu. Retour à sa place quand vous fermez les réglages.",
  ["Which addons are in use"] = "Quels addons sont utilisés",
  ["icon skins"] = "habillages d'icônes",
  ["keybinds read from its bars"] = "raccourcis lus sur ses barres",
  ["keybinds from its bars, data text launcher"] = "raccourcis de ses barres, lanceur de texte de données",
  ["launcher in Titan Panel"] = "lanceur dans Titan Panel",
  ["boss mod warnings"] = "alertes de boss mods",
  ["can read DMGAssist's picks (DMGAssistAPI)"] = "peut lire les choix de DMGAssist (DMGAssistAPI)",
  ["in use"] = "utilisé",
  ["found"] = "trouvé",
  ["which supported addons (Masque, ElvUI, Bartender, boss mods...) are found and in use"] = "quels addons pris en charge (Masque, ElvUI, Bartender, boss mods...) sont trouvés et utilisés",
  ["Written and maintained by %s"] = "Écrit et maintenu par %s",
  ["linked"] = "relié",
  ["Move the HUD in Blizzard's Edit Mode. Masque skins the icons. With a controller, keybinds show as its buttons (Display > Controller button names). Addon authors: DMGAssistAPI."] = "Déplacez le HUD dans le mode Édition de Blizzard. Masque habille les icônes. Avec une manette, les raccourcis s'affichent comme ses boutons (Affichage > Noms des boutons de manette). Pour les auteurs d'addons : DMGAssistAPI.",
  ["DMGAssist works with these when they are installed, with nothing to set up: Masque skins its icons, boss mods time defensives and interrupts, WeakAuras can read its picks."] = "DMGAssist fonctionne avec ceux-ci quand ils sont installés, sans rien régler : Masque habille ses icônes, les boss mods synchronisent défensifs et interruptions, WeakAuras peut lire ses choix.",
  ["Accuracy"] = "Précision",
  ["After each real fight, a grade from S+ to D pops up above the icons, with four parts: accuracy, always casting, reaction and cooldowns."] = "Après chaque vrai combat, une note de S+ à D apparaît au-dessus des icônes, en quatre parties : précision, toujours lancer, réaction et temps de recharge.",
  ["Always casting"] = "Toujours lancer",
  ["Average of the last %d"] = "Moyenne des %d derniers",
  ["Best"] = "Meilleure",
  ["Best grade, trend and where to improve for the spec you are in: see Grade report below Performance grade."] = "Meilleure note, tendance et points à améliorer pour votre spécialisation actuelle : voir Rapport de notes sous Note de performance.",
  ["Clears the best grade and history of the spec you are in. Other specs keep theirs."] = "Efface la meilleure note et l'historique de votre spécialisation actuelle. Les autres spécialisations gardent les leurs.",
  ["Cooldowns"] = "Temps de recharge",
  ["Drag the grade where you want it while the icons are unlocked or in Edit Mode; a sample shows while you do."] = "Faites glisser la note où vous voulez quand les icônes sont déverrouillées ou en mode Édition ; un exemple s'affiche pendant ce temps.",
  ["End-of-fight grade"] = "Note de fin de combat",
  ["Fight grade"] = "Note du combat",
  ["Fights shorter than this aren't graded, so trash pulls and a quick hit on a critter don't count."] = "Les combats plus courts ne sont pas notés, pour que les packs de trash et un coup rapide sur une bestiole ne comptent pas.",
  ["Forget every spec's grades"] = "Oublier les notes de toutes les spécialisations",
  ["Forget this spec's grades"] = "Oublier les notes de cette spécialisation",
  ["Grade report"] = "Rapport de notes",
  ["Grade stays on screen"] = "Durée d'affichage de la note",
  ["Grades every fight that lasts long enough: how often you pressed what slot 1 showed, how little time slot 1 sat ready, how fast you pressed it, and how quickly cooldowns were used. It never measures damage. Off: nothing is tracked or shown."] = "Note chaque combat assez long : combien de fois vous avez appuyé sur ce que montrait la case 1, le peu de temps où la case 1 est restée prête, la vitesse de vos appuis et la rapidité d'utilisation des temps de recharge. Ne mesure jamais les dégâts. Désactivé : rien n'est suivi ni affiché.",
  ["Grades for this spec forgotten."] = "Notes de cette spécialisation oubliées.",
  ["How long the grade stays before it fades out. It pops in quickly and fades in under a second."] = "Combien de temps la note reste avant de disparaître. Elle apparaît vite et s'efface en moins d'une seconde.",
  ["How your fights went in the spec you are in. Only fights long enough to grade count."] = "Le déroulement de vos combats dans votre spécialisation actuelle. Seuls les combats assez longs comptent.",
  ["Last %d fights (newest last)"] = "%d derniers combats (le plus récent à la fin)",
  ["Moves the grade back to its default place, just above the three icons."] = "Replace la note à sa position par défaut, juste au-dessus des trois icônes.",
  ["New best!"] = "Nouveau record !",
  ["No graded fights yet for this spec. Fight something for 20 seconds or more."] = "Aucun combat noté pour cette spécialisation. Combattez 20 secondes ou plus.",
  ["Nothing to improve: keep it up."] = "Rien à améliorer : continuez ainsi.",
  ["Performance grade"] = "Note de performance",
  ["Pops up a sample grade the way a real one shows, to check its place and how long it stays."] = "Affiche une note d'exemple comme une vraie, pour vérifier sa position et sa durée.",
  ["Put the grade back above the icons"] = "Remettre la note au-dessus des icônes",
  ["Reaction"] = "Réaction",
  ["Reset"] = "Réinitialiser",
  ["Shortest fight to grade"] = "Combat le plus court noté",
  ["Show a sample grade"] = "Afficher une note d'exemple",
  ["Show the grade after fights"] = "Afficher la note après les combats",
  ["Tip: press as the flash comes, or a little before: the game queues a press made just before it's ready."] = "Conseil : appuyez quand le flash arrive, ou un peu avant : le jeu met en file un appui fait juste avant que ce soit prêt.",
  ["Tip: press what slot 1 shows; slots 2 and 3 are what comes after it."] = "Conseil : appuyez sur ce que montre la case 1 ; les cases 2 et 3 sont la suite.",
  ["Tip: slot 1 asked for %s %d times when you pressed something else."] = "Conseil : la case 1 demandait %s %d fois quand vous avez appuyé sur autre chose.",
  ["Tip: slot 1 was ready for %.1f s without a press. Keep the global cooldown rolling."] = "Conseil : la case 1 est restée prête %.1f s sans appui. Gardez le temps de recharge global actif.",
  ["Tip: use major cooldowns, trinkets and your potion as soon as they show."] = "Conseil : utilisez les grands temps de recharge, les bijoux et votre potion dès qu'ils apparaissent.",
  ["Trend"] = "Tendance",
  ["Where to improve"] = "Points à améliorer",
  ["Your results"] = "Vos résultats",
  ["improving"] = "en progrès",
  ["slipping"] = "en baisse",
  ["steady"] = "stable",
}
